<?php
declare(strict_types=1);
$root=dirname(__DIR__);$dir=$root.'/storage/app/reports/ecotrade_catalog_audit';
function csvRows(string $p):array{$h=fopen($p,'rb');$head=fgetcsv($h,0,',','"','\\');$a=[];while(($r=fgetcsv($h,0,',','"','\\'))!==false)if(count($r)===count($head))$a[]=array_combine($head,$r);fclose($h);return $a;}
$path=$dir.'/family_evidence.csv';$rows=csvRows($path);$map=[];foreach($rows as $r)$map[strtolower($r['requested_group']).'|'.strtoupper((string)preg_replace('/[^A-Z0-9]+/i','',$r['requested_serial']))]=$r;
foreach(csvRows($root.'/storage/app/reports/ecotrade_full_review_results.csv') as $r){$k=strtolower($r['requested_group']).'|'.strtoupper((string)preg_replace('/[^A-Z0-9]+/i','',$r['requested_serial']));if(($r['buying_price']??'')===''||!isset($map[$k]))continue;$x=$map[$k];$x['ecotrade_product_ref']=$r['ecotrade_product']??$x['ecotrade_product_ref'];$x['ecotrade_url']=$r['ecotrade_url']??$x['ecotrade_url'];$x['product_type']=$r['product_type']??$x['product_type'];$x['classification']=$r['classification']??$x['classification'];$x['visible_price_label']='Price '.$r['buying_price'].' '.($r['currency']??'');$x['ecotrade_price_raw']=$r['buying_price'];$x['ecotrade_currency']=$r['currency']??'';$x['price_unit']=$r['price_unit']??'';$x['details_or_oem_refs']=$r['details']??$x['details_or_oem_refs'];$x['maker_if_visible']=$r['maker']??$x['maker_if_visible'];$x['years_if_visible']=$r['years']??$x['years_if_visible'];$x['match_confidence']=in_array(($r['status']??''),['FOUND'],true)?'EXACT':'AMBIGUOUS';$x['match_reason']=$r['match_reason']??$x['match_reason'];$x['notes']='Reused same-day authenticated review row with visible price; original observation date '.$r['observed_at'];$map[$k]=$x;}
$h=fopen($path,'wb');$header=array_keys($rows[0]);fputcsv($h,$header,',','"','\\');foreach($map as $r)fputcsv($h,$r,',','"','\\');fclose($h);file_put_contents($dir.'/family_evidence.json',json_encode(array_values($map),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));echo count($map).PHP_EOL;
